69	STATIC void dms_ioctl_close(int fd)
70	{
71	    struct davinci_intf_close_arg arg = {0};
72	    int ret;
73	
74	    if ((!FdIsValid(fd)) || (g_env_virt == true)) {
75	        return;
76	    }
77	
78	    ret = strcpy_s(arg.module_name, DAVINIC_MODULE_NAME_MAX, DAVINCI_INTF_MODULE_URD);
79	    if (ret != 0) {
80	        return;
81	    }
82	
83	    ret = ioctl(fd, DAVINCI_INTF_IOCTL_CLOSE, &arg);
84	    if (ret != 0) {
85	    }
86	}
