88	STATIC mmProcess dms_open_intf(void)
89	{
90	    mmProcess fd = DMS_INVALID_PID_OR_FD;
91	    int err = 0;
92	    int ret = 0;
93	
94	    /* to improve performance */
95	    if (FdIsValid(g_dms_fd) && (g_dms_tgid == getpid())) {
96	            return g_dms_fd;
97	    }
98	
99	#ifndef __linux
100	    if (g_dms_fd_mutex == NULL) {
101	        (void)mmMutexInit(&g_dms_fd_mutex);
102	    }
103	#endif
104	    (void)mmMutexLock(&g_dms_fd_mutex);
105	    if (FdIsValid(g_dms_fd)) {
106	        if (g_dms_tgid != getpid()) {
107	            g_dms_fd = (mmProcess)DMS_INVALID_PID_OR_FD;
108	        } else {
109	            fd = g_dms_fd;
110	            goto out;
111	        }
112	    }
113	#ifdef __linux
114	    fd = mmOpen2(DMS_DEVICE_FILE_NAME, M_RDWR|O_CLOEXEC, M_IRUSR);
115	    err = (__errno_location() != NULL ? errno : 0);
116	    ret = dms_ioctl_open(fd);
117	#else
118	    fd = devdrv_open_device_manager_win(&g_dms_fd);
119	#endif
120	    if (!FdIsValid(fd)) {
121	        DMS_ERR("Open failed. (dev_name=%s; fd=%d; g_dms_fd=%d; errno=%d)\n", DMS_DEVICE_FILE_NAME, fd, g_dms_fd, err);
122	        fd = (mmProcess)DMS_INVALID_PID_OR_FD;
123	        goto out;
124	    }
125	    if (ret != 0) {
126	        dms_ioctl_close(fd);
127	        (void)mmClose(fd);
128	        DMS_ERR("Dms ioctl open failed. (ret=%d; fd=%d)\n", ret, fd);
129	        fd = (mmProcess)DMS_INVALID_PID_OR_FD;
130	        goto out;
131	    }
132	
133	    g_dms_fd = fd;
134	    g_dms_tgid = getpid();
135	out:
136	    (void)mmMutexUnLock(&g_dms_fd_mutex);
137	    return fd;
138	}
139	
140	static void dms_close_intf(void)
141	{
142	    (void)mmMutexLock(&g_dms_fd_mutex);
143	    if (FdIsValid(g_dms_fd)) {
144	#if defined __linux
145	        if (g_dms_tgid == getpid()) {
146	            dms_ioctl_close(g_dms_fd);
147	            (void)mmClose(g_dms_fd);
148	        }
149	#endif
150	        g_dms_fd = (mmProcess)DMS_INVALID_PID_OR_FD;
151	        g_dms_tgid = (pid_t)DMS_INVALID_PID_OR_FD;
152	    }
153	    (void)mmMutexUnLock(&g_dms_fd_mutex);
154	}
