175	int DmsIoctl(int cmd, struct dms_ioctl_arg *ioarg)
176	{
177	    mmIoctlBuf ioctlBuf = {0};
178	    mmProcess fd;
179	    int ret;
180	    struct urd_ioctl_arg urd_ioarg = {0};
181	
182	    if (ioarg == NULL) {
183	        DMS_ERR("Para ioarg is NULL\n");
184	        return DRV_ERROR_PARA_ERROR;
185	    }
186	
187	    fd = dms_open_intf();
188	    if (!FdIsValid(fd)) {
189	        DMS_ERR("Open dms device failed. (fd=%d; cmd=%d)\n", fd, cmd);
190	        return DRV_ERROR_OPEN_FAILED;
191	    }
192	#ifndef CFG_FEATURE_SRIOV
193	    if (g_env_virt == true) {
194	        return DRV_ERROR_NOT_SUPPORT;
195	    }
196	#endif
197	    /* ioarg translate urd_ioctl_arg */
198	    urd_ioarg.cmd.main_cmd = ioarg->main_cmd;
199	    urd_ioarg.cmd.sub_cmd = ioarg->sub_cmd;
200	    urd_ioarg.cmd.filter = ioarg->filter;
201	    urd_ioarg.cmd.filter_len = ioarg->filter_len;
202	
203	    urd_ioarg.cmd_para.input = ioarg->input;
204	    urd_ioarg.cmd_para.input_len = ioarg->input_len;
205	    urd_ioarg.cmd_para.output = ioarg->output;
206	    urd_ioarg.cmd_para.output_len = ioarg->output_len;
207	
208	    ioctlBuf.inbuf = (void *)&urd_ioarg;
209	    ioctlBuf.inbufLen = sizeof(struct urd_ioctl_arg);
210	    ioctlBuf.outbuf = ioctlBuf.inbuf;
211	    ioctlBuf.outbufLen = ioctlBuf.inbufLen;
212	    ioctlBuf.oa = NULL;
213	    ret = mmIoctl(fd, cmd, &ioctlBuf);
214	    if (ret < 0) {
215	        ret = (__errno_location() != NULL ? errno : EIO);
216	        share_log_read_err(HAL_MODULE_TYPE_DEV_MANAGER);
217	    }
218	
219	    return ret;
220	}
