222	static inline int is_valid_user_errno(int err)
223	{
224	    return ((err >=0) && (err <= DRV_ERROR_POWER_OP_FAIL)) || (err == DRV_ERROR_NOT_SUPPORT);
225	}
226	
227	/*
228	    |kernel return   | ioctl return | errno |
229	    |ret=[, -4096]   | ret          |       |
230	    |ret=[-4095, -1] | -1           | |ret| |
231	    |ret=[0, ]       | ret          |       |
232	
233	    convert ioctl return/errno to userspace errno.
234	    support kernel return kernel errno(negative) or userspace errno.
235	*/
236	drvError_t ioctl_errno_convert(int ret, int errno_param)
237	{
238	    /* kernel return [-4095, -1] */
239	    if (ret == -1) { /* only if ret is -1, errno is set */
240	        return errno_to_user_errno(errno_param);
241	    }
242	    /* kernel return <= -4096 or >= 0 */
243	    if (is_valid_user_errno(ret)) {
244	        return ret;
245	    }
246	    return DRV_ERROR_IOCRL_FAIL;
247	}
248	
249	drvError_t DmsIoctlConvertErrno(unsigned long cmd, struct urd_ioctl_arg *ioarg)
250	{
251	    mmProcess fd;
252	    drvError_t ret;
253	
254	    fd = dms_open_intf();
255	    if (!FdIsValid(fd)) {
256	        DMS_ERR("Open dms device failed. (fd=%d; cmd=%lu)\n", fd, cmd);
257	        return DRV_ERROR_OPEN_FAILED;
258	    }
259	    if (ioarg == NULL) {
260	        DMS_ERR("ioctl arg is null. (fd=%d; cmd=%lu)\n", fd, cmd);
261	        return DRV_ERROR_PARA_ERROR;
262	    }
263	#ifndef CFG_FEATURE_SRIOV
264	    if (g_env_virt == true) {
265	        return DRV_ERROR_NOT_SUPPORT;
266	    }
267	#endif
268	    ret = ioctl(fd, cmd, ioarg);
269	    if (ret == 0) {
270	        return 0;
271	    }
272	    ret = ioctl_errno_convert(ret, errno);
273	    share_log_read_err(HAL_MODULE_TYPE_DEV_MANAGER);
274	    return ret;
275	}
