277	int dmanage_check_module_init(const char *module_name)
278	{
279	    char *buff = NULL;
280	    FILE *fp = NULL;
281	    size_t name_len;
282	    int retry_times= -1;
283	
284	    if (module_name == NULL) {
285	        DMS_ERR("para is NULL.\n");
286	        return -1;
287	    }
288	    name_len = strnlen(module_name, DEV_MODULE_INIT_INFO_LEN);
289	    if (name_len >= DEV_MODULE_INIT_INFO_LEN) {
290	        DMS_ERR("length out range. (length=%d)\n", name_len);
291	        return -1;
292	    }
293	    buff = (char *)malloc(DEV_MODULE_INIT_INFO_LEN);
294	    if (buff == NULL) {
295	        DMS_ERR("malloc memory error. (size=%d)\n", DEV_MODULE_INIT_INFO_LEN);
296	        return -1;
297	    }
298	
299	    do {
300	        fp = fopen(PROC_MOUDULE_FILE_NAME, "r");
301	        retry_times++;
302	    } while (fp == NULL && retry_times < MAX_FOPEN_RETRY_TIMES);
303	
304	    if (fp == NULL) {
305	        DMS_ERR("fopen error. (file=\"%s\"; errno:%d, retry_times=%d.)\n",
306	            PROC_MOUDULE_FILE_NAME, errno, retry_times);
307	        (void)free(buff);
308	        buff = NULL;
309	        return -1;
310	    }
311	    while (fgets(buff, DEV_MODULE_INIT_INFO_LEN, fp) != NULL) {
312	        if (strstr(buff, module_name) != NULL) {
313	            (void)free(buff);
314	            (void)fclose(fp);
315	            buff = NULL;
316	            fp = NULL;
317	            return 0;
318	        }
319	    }
320	
321	    (void)free(buff);
322	    (void)fclose(fp);
323	    buff = NULL;
324	    fp = NULL;
325	    return -1;
326	}
