328	int dms_run_proc(const char **arg)
329	{
330	    unsigned int status;
331	    unsigned int status1;
332	    pid_t tftpchildpid;
333	    pid_t wait_ppid;
334	    char *envp[] = { 0, NULL };
335	
336	    if (arg == NULL) {
337	        DMS_ERR("arg is null.\n");
338	        return DRV_ERROR_INVALID_HANDLE;
339	    }
340	    status = 0;
341	    tftpchildpid = vfork();
342	    if (tftpchildpid == 0) {
343	        (void)execve("/usr/bin/sudo", (void *)arg, envp);
344	        _exit(-1);
345	    }
346	    if (tftpchildpid == -1) {
347	        DMS_ERR("vfork fail.\n");
348	        return DRV_ERROR_INVALID_VALUE;
349	    }
350	    do {
351	        wait_ppid = waitpid(tftpchildpid, (int *)&status, 0);
352	    } while ((wait_ppid < 0) && (errno == EINTR));
353	    status1 = WIFEXITED(status);
354	    if (status1 == 0) {
355	        DMS_ERR("execve failed. (errno=%d; status1=%u)\n", errno, status1);
356	        return DRV_ERROR_INVALID_VALUE;
357	    }
358	
359	    status1 = WEXITSTATUS(status);
360	    if (status1 != 0) {
361	        DMS_ERR("cmd run failed. (errno=%d; status1=%u)\n", errno, status1);
362	        return DRV_ERROR_INVALID_VALUE;
363	    }
364	
365	    return DRV_ERROR_NONE;
366	}
