436	drvError_t dms_res_rollback_p2p(u32 target_dev_id, u32 target_peer_id, u32 tmp_cnt)
437	{
438	    u32 remaining_cnt, ret, dev_id, peer_phy_id;
439	    u32 p2p_type;
440	
441	    for (dev_id = target_dev_id; dev_id != UINT32_MAX; --dev_id) {
442	        for (peer_phy_id = target_peer_id; peer_phy_id != UINT32_MAX; --peer_phy_id) {
443	            (void)dms_get_p2p_restore_info(dev_id, peer_phy_id, &remaining_cnt, &p2p_type);
444	
445	            if ((dev_id == target_dev_id) && (peer_phy_id == target_peer_id)) {
446	                remaining_cnt -= tmp_cnt;
447	            }
448	
449	            while (remaining_cnt > 0) {
450	                ret = DmsDisableP2P(dev_id, peer_phy_id, p2p_type);
451	                if (ret != 0) {
452	                    DMS_ERR("p2p resotre rollback fail. (dev_id=%u; peer_phy_id=%u; ret=%d)\n",
453	                        dev_id, peer_phy_id, ret);
454	                    return ret;
455	                }
456	                remaining_cnt--;
457	            }
458	        }
459	    }
460	    DMS_INFO("p2p restore rollback success.\n");
461	
462	    return DRV_ERROR_NONE;
463	}
464	
465	drvError_t dms_res_enable_p2p(u32 dev_num)
466	{
467	    u32 dev_id, peer_phy_id, remaining_cnt = 0;
468	    u32 p2p_type;
469	    int ret;
470	
471	    for (dev_id = 0; dev_id < dev_num; ++dev_id) {
472	        for (peer_phy_id = 0; peer_phy_id < ASCEND_PDEV_MAX_NUM; ++peer_phy_id) {
473	            (void)dms_get_p2p_restore_info(dev_id, peer_phy_id, &remaining_cnt, &p2p_type);
474	
475	            while (remaining_cnt > 0) {
476	                ret = DmsEnableP2P(dev_id, peer_phy_id, p2p_type);
477	                if (ret != 0) {
478	                    DMS_ERR("p2p resotre enable fail, ready to rollback. (dev_id=%u; peer_phy_id=%u; ret=%d)\n",
479	                        dev_id, peer_phy_id, ret);
480	                    (void)dms_res_rollback_p2p(dev_id, peer_phy_id, remaining_cnt);
481	                    return ret;
482	                }
483	                remaining_cnt--;
484	            }
485	        }
486	    }
487	    DMS_INFO("p2p resotre success.\n");
488	
489	    return DRV_ERROR_NONE;
490	}
