192	    ret = dms_get_dsmi_errcode(voltage_err_code);
193	    if (ret != 0) {
194	        DMS_EX_NOTSUPPORT_ERR(ret, "get dsmi err_code failed, voltage_err_code = %d.\n", voltage_err_code);
195	        return ret;
196	    }
197	
198	    ret = dms_get_dsmi_errcode(current_err_code);
199	    if (ret != 0) {
200	        DMS_EX_NOTSUPPORT_ERR(ret, "get dsmi err_code failed, current_err_code = %d.\n", current_err_code);
201	        return ret;
202	    }
203	
204	    return ret;
205	}
