207	STATIC int dms_get_voltage_current_from_lp(unsigned int dev_id, unsigned int sub_cmd, void *out_buf,
208	                                      unsigned int *buf_size)
209	{
210	    int ret;
211	    struct ioctl_arg arg = {0};
212	    unsigned int arg_size = sizeof(struct ioctl_arg);
213	
214	    if ((sub_cmd >= DSMI_LP_SUB_CMD_MAX) || out_buf == NULL || buf_size == NULL) {
215	        DMS_ERR("input para illegal, sub_cmd=%u, out_buf or buf_size is null\n", sub_cmd);
216	        return DRV_ERROR_PARA_ERROR;
217	    }
218	
219	    if (*buf_size < BUFSIZE_MIN) {
220	        DMS_ERR("input para illegal, buf_size=%u\n", *buf_size);
221	        return DRV_ERROR_PARA_ERROR;
222	    }
223	
224	    arg.dev_id = dev_id;
225	    arg.vfid = DMS_VF_ID_PF;
226	    arg.type = DMS_LPM_SOC_ID; // core_id
227	
228	    ret = DmsGetDeviceInfo(dev_id, DMS_MAIN_CMD_LP, sub_cmd, (void *)&arg, &arg_size);
229	    if (ret != 0) {
230	        DMS_ERR("DmsGetDeviceInfo failed, devid(%u), sub_cmd(%u), ret(%d).\n", dev_id, sub_cmd, ret);
231	        return ret;
232	    }
233	
234	    ret = DmsCheckLpErrcode(&arg);
235	    if (ret != 0) {
236	        DMS_EX_NOTSUPPORT_ERR(ret, "check lp_errcode failed.\n");
237	        return ret;
238	    }
239	
240	    // 4 bytes voltage, 4 bytes current
241	    ret = memcpy_s(out_buf, sizeof(arg.data1), &arg.data1, sizeof(arg.data1));
242	    if (ret != 0) {
243	        DMS_ERR("memcpy_s failed, ret = %d\n", ret);
244	        return DRV_ERROR_MEMORY_OPT_FAIL;
245	    }
246	    ret = memcpy_s(((char *)out_buf + sizeof(arg.data1)), sizeof(arg.data3), &arg.data3, sizeof(arg.data3));
247	    if (ret != 0) {
248	        DMS_ERR("memcpy_s failed, ret = %d\n", ret);
249	        return DRV_ERROR_MEMORY_OPT_FAIL;
250	    }
251	
252	    *buf_size = sizeof(arg.data1) + sizeof(arg.data3);
253	    return DRV_ERROR_NONE;
254	}
