215	static drvError_t dms_get_ioctl(DSMI_MAIN_CMD main_cmd, struct dms_filter_st filter, struct dms_get_device_info_in in,
216	    unsigned int *size)
217	{
218	    struct dms_ioctl_arg ioarg = {0};
219	    struct dms_get_device_info_out out = {0};
220	    int ret;
221	
222	    ioarg.main_cmd = DMS_GET_GET_DEVICE_INFO_CMD;
223	    ioarg.sub_cmd = ZERO_CMD;
224	    ioarg.filter = &filter.filter[0];
225	    ioarg.filter_len = filter.filter_len;
226	    ioarg.input = (void *)&in;
227	    ioarg.input_len = sizeof(struct dms_get_device_info_in);
228	    ioarg.output = (void *)&out;
229	    ioarg.output_len = sizeof(struct dms_get_device_info_out);
230	
231	    ret = DmsIoctl(DMS_IOCTL_CMD, &ioarg);
232	    /* when main_cmd is DSMI_MAIN_CMD_PCIE, only DSMI_PCIE_SUB_CMD_PCIE_INFO sub_cmd calls current function */
233	    if (ret != 0 && (main_cmd == DSMI_MAIN_CMD_SEC || main_cmd == DSMI_MAIN_CMD_PCIE)) {
234	        ret = dms_errno_convert(ret);
235	        if (ret != 0) {
236	            DMS_EX_NOTSUPPORT_ERR(ret, "Get device info failed. (ret=%d; filter:\"%s\")\n", ret, filter.filter);
237	            return ret;
238	        }
239	        DMS_DEBUG("Set device info success.\n");
240	        return DRV_ERROR_NONE;
241	    }
242	
243	    ret = errno_to_user_errno(ret);
244	    if (ret != 0) {
245	        if (main_cmd != DSMI_MAIN_CMD_HCCS) {
246	            /* it is used to be compatible with the old errno. */
247	            ret = (ret == DRV_ERROR_OPER_NOT_PERMITTED) ? DRV_ERROR_IOCRL_FAIL : ret;
248	        }
249	        DMS_EX_NOTSUPPORT_ERR(ret, "Get Device info failed. (ret=%d; filter:\"%s\")\n", ret, filter.filter);
250	        return ret;
251	    }
252	    *size = out.out_size;
253	    DMS_DEBUG("Get Device info success.\n");
254	    return DRV_ERROR_NONE;
255	}
