    in.dev_id = dev_id;
    in.sub_cmd = sub_cmd;
    in.buff = buf;
    in.buff_size = *size;

    ioarg.main_cmd = DMS_GET_GET_DETECT_INFO_CMD;
    ioarg.sub_cmd = ZERO_CMD;
    ioarg.filter = &filter.filter[0];
    ioarg.filter_len = filter.filter_len;
